#!/usr/bin/env python3
# -----------------------------------------------------------------------------
# Generate the release-notes list in web/release-notes.html from the per-release
# HTML fragments in dist/release-notes/*.md, newest-first.
#
# The dist/release-notes/<version>.md files are the same HTML embedded in the
# Sparkle appcast + GitHub releases. This stitches them into one page so the
# website carries a full changelog without a separate hand-maintained copy
# (which would drift — see the in-app Help article that did exactly that).
#
# Usage (paths optional; default to repo layout):
#   dist/web-release-notes.py [<release-notes-dir> <page-file>]
#
# Behaviour:
#   • Versions sorted semver-descending; most recent on top.
#   • Each release's own leading "SherlockEQ <v>" <h2> is replaced with a
#     styled header (version + link to the GitHub tag).
#   • Per-release "Not a medical device" / "Previous release" boilerplate is
#     dropped — the page footer carries the standing disclaimer and every
#     version is already on the one page.
#   • Only the region between the generator markers in the page is rewritten;
#     the page chrome (nav, hero, footer) is hand-authored and left untouched.
#   • Idempotent: same inputs → same output.
#
# Exit codes: 0 on success; non-zero only on a real error (missing dir/markers,
# no release files). ship.sh treats a non-zero result as a warning.
# -----------------------------------------------------------------------------
import glob
import os
import re
import sys

REPO = "https://github.com/smbrownai/SherlockEQ"
START = "<!-- RELEASE NOTES START (generated by dist/web-release-notes.py) -->"
END = "<!-- RELEASE NOTES END -->"

# Section headings dropped from each per-release fragment on the changelog page.
SKIP = re.compile(r"\s*<h3>\s*(not a medical device|previous release)\s*</h3>", re.I)


def version_key(version):
    m = re.match(r"(\d+)\.(\d+)\.(\d+)(?:-(.+))?$", version)
    if not m:
        return (0, 0, 0, 0, "")
    major, minor, patch, pre = m.groups()
    # A final release outranks its pre-releases of the same x.y.z.
    return (int(major), int(minor), int(patch), 0 if pre is None else -1, pre or "")


def clean_body(fragment):
    """Drop the leading 'SherlockEQ <v>' heading and the boilerplate sections,
    keeping the summary paragraph and all real content sections (including
    historical ones like Acknowledgments / 'If you installed …')."""
    frag = fragment.strip()
    # Split into the lead (h2 + summary) and one chunk per <h3> section.
    chunks = re.split(r"(?=<h3>)", frag)
    lead, sections = chunks[0], chunks[1:]
    # Strip the release's own <h2> title — the page renders its own header.
    lead = re.sub(r"^\s*<h2>.*?</h2>\s*", "", lead, count=1, flags=re.DOTALL | re.I)
    kept = [s for s in sections if not SKIP.match(s)]
    body = (lead + "".join(kept)).strip()
    # Re-indent each top-level line to sit inside the article markup.
    return "\n".join(
        ("            " + line if line.strip() else "") for line in body.splitlines()
    )


def render_article(version, fragment):
    tag = f"v{version}"
    body = clean_body(fragment)
    return (
        f'        <article class="rn-item" id="{tag}">\n'
        f'          <div class="rn-head">\n'
        f'            <h2>{version}</h2>\n'
        f'            <a class="rn-tag" href="{REPO}/releases/tag/{tag}">'
        f'{tag} on GitHub <i data-lucide="arrow-up-right" '
        f'style="width:12px;height:12px"></i></a>\n'
        f'          </div>\n'
        f'          <div class="rn-body">\n'
        f"{body}\n"
        f'          </div>\n'
        f"        </article>"
    )


def main(argv):
    here = os.path.dirname(os.path.abspath(__file__))
    repo_root = os.path.dirname(here)
    notes_dir = argv[1] if len(argv) > 1 else os.path.join(repo_root, "dist", "release-notes")
    page = argv[2] if len(argv) > 2 else os.path.join(repo_root, "web", "release-notes.html")

    files = glob.glob(os.path.join(notes_dir, "*.md"))
    versions = []
    for f in files:
        v = os.path.splitext(os.path.basename(f))[0]
        if re.match(r"\d+\.\d+\.\d+", v):
            versions.append((v, f))
    if not versions:
        sys.stderr.write(f"error: no release-notes files in {notes_dir}\n")
        return 1
    versions.sort(key=lambda vf: version_key(vf[0]), reverse=True)

    articles = []
    for v, f in versions:
        fragment = open(f, encoding="utf-8").read()
        articles.append(render_article(v, fragment))
    generated = "\n\n".join(articles)

    try:
        html = open(page, encoding="utf-8").read()
    except OSError as e:
        sys.stderr.write(f"error: cannot read page: {e}\n")
        return 1

    if START not in html or END not in html:
        sys.stderr.write(
            f"error: {page} is missing the generator markers\n"
            f"       {START}\n       {END}\n"
        )
        return 1

    block = f"{START}\n{generated}\n        {END}"
    updated = re.sub(
        re.escape(START) + r".*?" + re.escape(END),
        lambda _: block,
        html,
        flags=re.DOTALL,
    )
    open(page, "w", encoding="utf-8").write(updated)
    print(f"web release notes: wrote {len(versions)} versions to {page}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
